-- markdata-pty-ltd-monument-park (owner)
UPDATE businesses SET description = 'MarkData is a marketing and strategic research company at Office@51, 51 Gemsbok Avenue, Monument Park, Pretoria, specialising in qualitative and quantitative market research, strategic insights, consulting and research development. Its work helps organisations understand consumers, markets, behaviour and broader social or business trends, with research solutions built around each client''s specific requirements. The company has roots going back to research work associated with the Human Sciences Research Council and was re-established as a private, fully independent company in 1996. It is a member of the Southern African Marketing Research Association. MarkData serves businesses, government departments, universities and other organisations across sectors such as marketing, media, financial services, retail, manufacturing and healthcare, working primarily in South Africa while also undertaking projects elsewhere in Africa. It suits organisations that need research-based evidence to support business or policy decisions.', description_enriched_at = datetime('now') WHERE slug = 'markdata-pty-ltd-monument-park' AND description = 'Markdata (Pty) Ltd is a business and management consulting firm based in Monument Park, Pretoria.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
