UPDATE businesses SET description = 'Orchards Pharmacy is a community pharmacy at Orchards Shop Centre on Garden Road in The Orchards, Pretoria, providing prescription and over-the-counter medicines, health products and everyday pharmacy assistance. As a local pharmacy, it offers a more neighbourhood-focused alternative to larger national pharmacy chains, serving residents and families in The Orchards, Akasia and the surrounding northern Pretoria area. Customers use it to collect prescriptions, buy medicines and health products, and get general pharmacy advice close to home. It trades on weekdays with more limited weekend hours. Orchards Pharmacy suits residents of The Orchards and Akasia who want a local, community-based pharmacy for everyday medicine and healthcare needs rather than travelling to a larger shopping centre.', description_enriched_at = datetime('now') WHERE slug = 'orchards-pharmacy-the-orchards' AND description = 'Orchards Pharmacy & Med Depot is a retail pharmacy and clinic in The Orchards, Akasia.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
